# POST /api/sheets/{sheetId}/claims/paste — add a DRAFT claim per pasted line. Body {"text":"..."}, lines of
# name,amount,date,note (a blank date is the entry date, else the sheet's today; the note may hold commas or be absent, and may end in " #<reference>": that part is the claim's reference, not its note). Every line is
# checked first, by the claim form's rules and against a person of that name (ignoring case) on the sheet: 400 for a
# bad line, a name not on the sheet, a reference already used on the sheet or repeated in the paste (ignoring case), 422 for a date inside a closed period or after the person's retirement —
# and then nothing is stored. Responds {"added":n}.
viewer:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: archived
  govern: [ transaction ]
archived:
  class: net.officefloor.hq.app.sheet.RefuseArchived
  next: snapshot
  govern: [ transaction ]
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  next: validate
  govern: [ transaction ]
validate:
  class: net.officefloor.hq.app.claim.ValidatePaste
  next: add
  govern: [ transaction ]
add:
  class: net.officefloor.hq.app.claim.AddPastedClaims
  next: rollup
  govern: [ transaction ]
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.claim.RespondWithPasted
  govern: [ transaction ]
# PUT /api/sheets/{sheetId}/claims/{claimId}/status/{status} — move a claim to OPEN, SETTLED, VOID or DELETED.
# A DRAFT claim can be DELETED (counting nowhere), and a DELETED one restored to DRAFT on the sheet's today it was
# deleted (CLAIM_RESTORED).
# DRAFT -> OPEN -> SETTLED, and DRAFT, OPEN or PENDING -> VOID; a steward may also void a SETTLED claim within 7 days
# of its settlement (the status log's SETTLED date) by the sheet's today. A clerk settling a claim above the clerk limit
# makes it PENDING; opening a DRAFT claim whose due-by falls in a period with a cap is refused (409) while its person
# already has that many OPEN or PENDING claims in it; from PENDING a steward (not its opener) approves it (SETTLED) or rejects it (OPEN, with a
# "reason" in the body). Any other change is refused with 409 and nothing is stored. 404 for a claim not on the
# sheet; 422 for a claim dated inside a closed period, or for a settle or approve of a claim with no proof whose due is
# above the proof threshold in force on its date, or for an open of a DRAFT claim with an empty note whose due is above
# the note threshold in force on its date.
viewer:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: archived
  govern: [ transaction ]
archived:
  class: net.officefloor.hq.app.sheet.RefuseArchived
  next: snapshot
  govern: [ transaction ]
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  next: load
  govern: [ transaction ]
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  next: closed
  govern: [ transaction ]
closed:
  class: net.officefloor.hq.app.claim.RefuseClosedClaim
  next: apply
  govern: [ transaction ]
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  next: audit
  govern: [ transaction ]
audit:
  class: net.officefloor.hq.app.claim.AuditClaimStatus
  next: notify
  govern: [ transaction ]
notify:
  class: net.officefloor.hq.app.watch.NotifyWatchers
  next: rollup
  govern: [ transaction ]
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.claim.RespondWithEditedClaim
  govern: [ transaction ]
# PUT /api/sheets/{sheetId}/claims/{claimId} — edit a claim's amount, date, note, the number it corrects and its reference. Body as for an
# add; refused the same way (400), 404 for a claim not on the sheet, and 422 for a claim that is not a
# draft, whose due-by (kept by the edit) is inside a closed period, whose editor another user has open (locked), or that has
# lines and is typed another amount than they add up to.
